package com.example.user.scheduler; import com.example.user.service.MailDeliveryService; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; @Component public class MailDeliveryWorker {private final MailDeliveryService service;public MailDeliveryWorker(MailDeliveryService s){service=s;}@Scheduled(fixedDelayString="${mail.delivery-interval-ms:10000}")public void work(){service.deliverDue();}}
